#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Senhas das personas do teste real: troca as senhas das cinco personas no Supabase Auth e leva as mesmas
# variáveis para o ambiente de nuvem do Claude Code, para o npm run teste:real rodar na sua máquina e nas
# sessões na nuvem com os mesmos valores.
#
# Rode num terminal interativo (de qualquer pasta do repositório), depois do scripts/wizard-teste-real.sh:
#   scripts/wizard-senhas-das-personas.sh
# Para outro projeto: SUPABASE_REF=<ref> scripts/wizard-senhas-das-personas.sh
# No Windows, rode pelo Git Bash: o Windows PowerShell não executa .sh.

TOTAL_STAGES=3

RAIZ="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$RAIZ"
ENV_FILE="projeto-althius-frontend/.env.local"
SUPABASE_REF="${SUPABASE_REF:-ycbdilsmydvzezhlymty}"
PAINEL="https://supabase.com/dashboard/project/$SUPABASE_REF"
PERSONAS=(RESPONSAVEL MEMBRO ADMIN OUTRO_WS SEM_PARTICIPACAO)
COMUNS=(VITE_SUPABASE_URL VITE_SUPABASE_PUBLISHABLE_KEY TESTE_WORKSPACE_A TESTE_WORKSPACE_B)

[[ -t 0 ]] || { printf 'Rode este wizard num terminal interativo.\n' >&2; exit 1; }

# nova_senha imprime uma senha aleatória com minúscula, maiúscula, dígito e símbolo.
nova_senha() {
  local s
  s=$(LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom 2>/dev/null | head -c 20 || true)
  [[ ${#s} -eq 20 ]] || s=$(openssl rand -hex 10)
  printf '%sAa9-' "$s"
}

# copiar TEXTO põe o texto na área de transferência; falha se não houver como.
copiar() {
  if   command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}

# Os e-mails, a chave publicável e os Workspaces vêm do wizard-teste-real.sh.
EXIGIDAS=("${COMUNS[@]}")
for p in "${PERSONAS[@]}"; do EXIGIDAS+=("TESTE_${p}_EMAIL"); done
for chave in "${EXIGIDAS[@]}"; do
  if [[ -z "$(_existing "$chave" || true)" ]]; then
    printf 'Falta %s em %s: rode scripts/wizard-teste-real.sh antes.\n' "$chave" "$ENV_FILE" >&2
    exit 1
  fi
done

banner "Senhas das personas do teste real"

stage "Senhas novas no Supabase Auth"
say "Cada persona ganha uma senha nova, gravada no .env.local e trocada no Supabase Auth."
VALORES=""
for p in "${PERSONAS[@]}"; do
  senha=$(nova_senha)
  write_env "TESTE_${p}_SENHA" "$senha"
  VALORES="${VALORES:+$VALORES,
}  ('$(_existing "TESTE_${p}_EMAIL")', '$senha')"
done
SQL="update auth.users u
set encrypted_password = extensions.crypt(v.senha, extensions.gen_salt('bf')), updated_at = now()
from (values
$VALORES
) as v(email, senha)
where lower(u.email) = v.email
returning u.email;"
open_url "$PAINEL/sql/new"
if copiar "$SQL"; then
  step "O SQL já está na área de transferência: cole no editor e clique em Run."
else
  step "Copie o SQL abaixo, cole no editor e clique em Run."
  printf '\n%s\n\n' "$SQL"
fi
step "O resultado deve ter 5 linhas, uma por persona."
note "O SQL traz as senhas de teste: se o SQL Editor guardar a consulta como snippet, apague-a depois."
pause "Tecle Enter com as 5 linhas"

stage "Variáveis no ambiente de nuvem do Claude Code"
say "As sessões do Claude Code na nuvem não têm o seu .env.local: elas leem as mesmas"
say "variáveis cadastradas no ambiente de nuvem."
BLOCO=""
for chave in "${COMUNS[@]}"; do BLOCO+="$chave=$(_existing "$chave")"$'\n'; done
for p in "${PERSONAS[@]}"; do
  for campo in EMAIL SENHA; do BLOCO+="TESTE_${p}_${campo}=$(_existing "TESTE_${p}_${campo}")"$'\n'; done
done
open_url "https://claude.ai/code"
step "Abra uma sessão com o repositório Althius."
step "Clique no nome do ambiente de nuvem, na barra de título da sessão, e depois em Editar (Edit)."
if copiar "$BLOCO"; then
  step "Em Variáveis de ambiente (Environment variables), cole o bloco que já está na área de transferência e salve."
else
  step "Em Variáveis de ambiente (Environment variables), cole o bloco abaixo e salve."
  printf '\n%s\n' "$BLOCO"
fi
note "As sessões novas recebem as variáveis; as que já estavam abertas, não."
pause "Tecle Enter depois de salvar"

stage "Conferir com o teste real"
say "Roda as 20 regras do ticket 01 com as senhas novas, pela mesma API do app."
note "Precisa do npm install já feito em projeto-althius-frontend."
if (cd projeto-althius-frontend && npm run teste:real); then
  pause "Tecle Enter para terminar"
else
  SKIPPED+=("Teste real: alguma persona não entrou ou alguma regra falhou; confira as 5 linhas do SQL")
  pause "Tecle Enter para ver o resumo"
fi

finish
note "Numa sessão nova do Claude Code, o npm run teste:real já roda com estas variáveis."
printf '\n'
